#!/usr/bin/env python3
"""Add the cross-family cards and apply normalized crosswalks to all cards."""
from __future__ import annotations

import sys
from pathlib import Path

ROOT = Path(__file__).resolve().parents[1]
sys.path.insert(0, str(ROOT / "scripts"))
from generate_cards import CARDS, COMMON_SAFE, DIRECTORY_MAP, card, render  # noqa: E402


def extra(id, title, family, cwe, capec, aliases, surfaces, platforms, summary, source, sink, signals, refs, provenance, body):
    config_signals = [f"Configuration flags, defaults or error paths can bypass {title.lower()}.", "Inspect deployment, proxy, identity and resource-limit settings that affect the control."]
    architecture_signals = [f"Trace {source} to {sink} across synchronous, asynchronous, alternate-protocol and provider boundaries."]
    record = card(
        id, title, family, cwe, capec, aliases, surfaces, ["any"], ["framework-agnostic"], platforms,
        ["An untrusted or lower-trust input reaches the described boundary.", "A security control is expected at or before the sink but is absent, incomplete or applied on only one path."],
        ["untrusted input to application", "application to privileged/resource sink"],
        {"sources": [source], "transformations": ["decode, normalize or parse input", "application-specific routing"], "controls": ["validation or policy control if present"], "sinks": [sink], "authorization_points": ["the decision point immediately before the sink"]},
        signals, config_signals, architecture_signals,
        ["What exact source and sink are reachable?", "Which control should run before the sink?", "Do alternate protocols, retries or error paths differ?"], COMMON_SAFE, ["The named library or endpoint is only a signal; confirm reachability and the exact sink."],
        ["security boundary bypass", "confidentiality/integrity/availability impact"], ["Severity depends on the asset, privilege and blast radius."], ["Reachability and a controllable input are required; use test fixtures only."],
        ["Enforce the control at the sink-facing service boundary.", "Make policy explicit, deny by default and cover alternate/async paths.", "Add telemetry and bounded failure behaviour."], ["Typed inputs and explicit policy checks.", "Least privilege, isolation and bounded resource use."],
        ["Add a local or staging negative test using a canary and assert the control blocks the unsafe sink."], refs, provenance, body
    )
    record["summary"] = summary
    return record


