def main() -> int:
    all_cards = CARDS + EXTRA
    for record in all_cards:
        if record["id"] == "vuln.injection.template":
            record["aliases"] = ["server-side template injection", "template source injection"]
        if record["id"] == "vuln.secrets.data-minimization":
            record["id"] = "vuln.privacy.data-minimization"
        record.update(MAPS.get(record["id"], {}))
        record["related_cwe"] = RELATED_CWE.get(record["id"], [])
        record["related_vulnerabilities"] = RELATED_VULNS.get(record["id"], [])
        path = ROOT / "vulnerabilities" / DIRECTORY_MAP.get(record["family"], record["family"]) / (record["id"].split(".", 2)[-1] + ".md")
        path.parent.mkdir(parents=True, exist_ok=True)
        path.write_text(render(record.copy()), encoding="utf-8")
    print(f"generated {len(all_cards)} atomic cards")
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
